/// Whether a `new Date(...)` call is pure.
///
/// `Date` is pure with no arguments (current time), a numeric literal (timestamp), or a string
/// literal (parsed date). An unknown variable reference could be an object whose `ToPrimitive`
/// runs user code, so it is not pure.
fn is_pure_date_constructor(args: &[Argument<'_>]) -> bool {
    match args.first() {
        None => true,
        Some(arg) => matches!(
            arg.as_expression(),
            Some(Expression::NumericLiteral(_) | Expression::StringLiteral(_))
        ),
    }
}

/// Whether a `new ArrayBuffer(...)` call is pure.
