/// `ArrayBuffer` coerces its argument to an index via `ToNumber`. It is pure with no arguments or
/// a numeric literal, but an unknown variable reference could be an object whose `ToPrimitive`
/// runs user code.
fn is_pure_buffer_constructor(args: &[Argument<'_>]) -> bool {
    match args.first() {
        None => true,
        Some(arg) => matches!(arg.as_expression(), Some(Expression::NumericLiteral(_))),
    }
}

/// Whether a `new Int8Array(...)` (and other `TypedArray`) call is pure.
///
/// A `TypedArray` constructor is pure with no arguments or a numeric literal (length). When given
/// an object, it iterates it via `Symbol.iterator` if present; a plain object literal has no custom
/// iterator so it is pure, but an object literal defining a custom iterator runs user code. An
/// unknown variable reference could be anything, so it is not pure.
fn is_pure_typed_array_constructor(args: &[Argument<'_>]) -> bool {
    match args.first() {
        None => true,
        Some(arg) => match arg.as_expression() {
            Some(Expression::NumericLiteral(_)) => true,
            Some(Expression::ObjectExpression(obj)) => !object_defines_custom_iterator(obj),
            _ => false,
        },
    }
}

