use rustc_hash::FxHashSet;

use oxc_allocator::Allocator;
use oxc_ast::ast::{Expression, IdentifierReference, Statement};
use oxc_ecmascript::{
    GlobalContext,
    side_effects::{
        MayHaveSideEffects, MayHaveSideEffectsContext, PropertyReadSideEffects, is_pure_function,
    },
};
use oxc_parser::Parser;
use oxc_span::SourceType;

struct Ctx {
    global_variable_names: FxHashSet<&'static str>,
}

impl<'a> GlobalContext<'a> for Ctx {
    fn is_global_reference(&self, ident: &IdentifierReference<'a>) -> bool {
        self.global_variable_names.contains(ident.name.as_str())
    }
}

impl MayHaveSideEffectsContext<'_> for Ctx {
    fn annotations(&self) -> bool {
        true
    }
    fn manual_pure_functions(&self, callee: &Expression) -> bool {
        is_pure_function(callee, &[])
    }
    fn property_read_side_effects(&self) -> PropertyReadSideEffects {
        PropertyReadSideEffects::All
    }
    fn property_write_side_effects(&self) -> bool {
        true
    }
    fn unknown_global_side_effects(&self) -> bool {
        true
    }
}

fn check(src: &str, expected: bool) {
    let ctx = Ctx {
        global_variable_names: GLOBALS["builtin"]
            .keys()
            .copied()
            .chain(["arguments", "URL"])
            .collect(),
    };
    let allocator = Allocator::default();
    let ret = Parser::new(&allocator, src, SourceType::mjs()).parse();
    let Some(Statement::ExpressionStatement(stmt)) = &ret.program.body.first() else {
        panic!("no expr stmt: {src}");
    };
    let got = stmt.expression.may_have_side_effects(&ctx);
    let mark = if got == expected { "ok " } else { "FAIL" };
    println!("[{mark}] {src} => got={got} expected={expected}");
}

fn main() {
    // String
    check("new String()", false);
    check("new String('x')", false);
    check("new String(5)", false);
    check("new String(true)", false);
    check("new String(null)", false);
    check("new String(obj)", true);
    check("new String({})", false);
    check("new String({ toString() { return 'x' } })", true);
    // Number
    check("new Number()", false);
    check("new Number(5)", false);
    check("new Number('x')", false);
    check("new Number(true)", false);
    check("new Number(null)", false);
    check("new Number(obj)", true);
    check("new Number({})", false);
    check("new Number({ valueOf() { return 1 } })", true);
    // Date
    check("new Date()", false);
    check("new Date(123)", false);
    check("new Date('2020')", false);
    check("new Date(obj)", true);
    // ArrayBuffer (buffer)
    check("new ArrayBuffer()", false);
    check("new ArrayBuffer(8)", false);
    check("new ArrayBuffer(obj)", true);
    // TypedArrays
    check("new Int8Array()", false);
    check("new Uint8Array(5)", false);
    check("new Float64Array(obj)", true);
    check("new Int16Array({})", false);
    check("new Int32Array({ [Symbol.iterator]() {} })", true);
    check("new BigInt64Array({ [Symbol['iterator']]() {} })", true);
    // Object always pure
    check("new Object(obj)", false);
    check("new Object({})", false);
    check("new Object({ toString() {} })", false);
    // Boolean always pure
    check("new Boolean(obj)", false);
    check("new Boolean({ valueOf() {} })", false);
    // Error family always pure
    check("new Error(obj)", false);
    check("new TypeError(obj)", false);
    check("new RangeError(obj)", false);
}
